        for px, py in list(opT)[:64]:
            for nx, ny in neigh(px, py):
                if (nx, ny) not in selfT and (nx, ny) not in obs and (nx, ny) not in opT:
                    if (nx, ny) in unT:
                        candidates.append((nx, ny))
        if not candidates and unT:
            candidates = list(unT)

    if not candidates:
        # Fallback: move toward nearest unclaimed cell; avoid obstacles by considering immediate moves only.
        candidates = list(unT) if unT else [(sx, sy)]

    seen = set()
    candidates2 = []
    for c in candidates:
        if c not in seen:
            seen.add(c)
            candidates2.append(c)
        if len(candidates2) > 25:
            break
    candidates = candidates2

    # Score: closeness to target, and prefer targets that are "farther" from self (break away) but "near" to opponent.
    # Also, if opponent territory exists adjacent to target, it increases pressure.
    for tx, ty in candidates:
        if (tx, ty) in obs:
            continue
        d_me = abs(tx - sx) + abs(ty - sy)
        d_op = abs(tx - ox) + abs(ty - oy)
        adj_op = 0
        for nx, ny in neigh(tx, ty):
            if (nx, ny) in opT:
                adj_op += 1
        # Strongly prefer edge targets; slight bias to not collide with opponent directly.
        sc = 4 * adj_op - 1.2 * d_me + 0.35 * d_op
        if sc > best_sc or (sc == best_sc and (tx, ty) < best):
            best_sc = sc
            best = (tx, ty)

    if best is None:
        return [0, 0]

    # Choose immediate move that reduces distance to best, with obstacle/territory safety via deterministic tie-break.
    bx, by = best
    best_move = [0, 0]
    best_ms = -10**18
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not inside(nx, ny) or (nx, ny) in obs:
            continue
        d = abs(nx - bx) + abs(ny - by)
        # If we step into opponent territory, it's beneficial (flips on entry), so reward that.
        into_op = 1 if (nx, ny) in opT else 0
        # Slightly penalize stepping into self territory (to avoid wasting on already owned cells).
        into_self = 1 if (nx, ny) in selfT else 0
        ms = -d + 5.0 * into_op - 0.8 * into_self
        if ms > best_ms or (ms == best_ms and [dx, dy] < best_move):
            best_ms = ms
            best_move = [dx, dy]

    return best_move

